const root = flow.get("lights", STORE);
if (!root || typeof root !== "object" || !root.config) {
    node.error("flow.lights.config fehlt im Store file: zuerst manuell initialisieren", msg);
    return null;
}
const config = root.config;
const area = String(msg.area || "").trim();
const topic = String(msg.topic || "").toLowerCase();
const areaCfg = config[area];
const group = areaCfg?.["config group"];
if (!group || !Array.isArray(group["config segments"])) {
    node.error("Unbekannte Lichtgruppe: " + area, msg);
    return null;
}
root.status = root.status || {};
root.status.channels = root.status.channels || {};
const values = root.status.channels;
const nm = flow.get("nightMode", STORE) || {};
// Migration: bisherige Sollwerte einmalig in den Nachtmodus-Context verschieben.
// Vorhandene Backupwerte haben Vorrang; alte Werte nur ergaenzen.
nm.ChannelBackupPreNightMode = nm.ChannelBackupPreNightMode || {};
if (root.desiredChannels && typeof root.desiredChannels === "object") {
    for (const [channel, value] of Object.entries(root.desiredChannels)) {
        if (nm.ChannelBackupPreNightMode[channel] === undefined) {
            nm.ChannelBackupPreNightMode[channel] = value;
        }
    }
    delete root.desiredChannels;
}
const desired = nm.ChannelBackupPreNightMode;
const isRgb = group.type === "rgb" && (area === "innen" || area === "aussen");
const nightActive = isRgb && (topic === "night_apply" ? msg.payload?.night === true : nm.active === true);
const colors = ["r", "g", "b", "w", "ww"];
const clamp = (v, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, Number(v) || 0));
const all = new Map();
for (const segment of group["config segments"]) {
    for (const color of colors) {
        const c = segment.channels?.[color];
        if (!c || c.channel === null || c.channel === undefined || c.channel === "") continue;
        const channel = Number(c.channel);
        if (!Number.isInteger(channel)) continue;
        const delay = Math.max(0, Number(c["on delay"]) || 0);
        const old = all.get(channel);
        if (!old || delay >= old.delay) {
            all.set(channel, { ...c, channel, color, delay });
        }
    }
}
// Beim Upgrade der bestehenden Installation Sollwerte aus gespeicherten Kanalwerten uebernehmen.
for (const n of all.keys()) {
    if (desired[n] === undefined && values[n] !== undefined) desired[n] = Number(values[n]) || 0;
}
function groupState(name) {
    const segs = config[name]?.["config group"]?.["config segments"];
    if (!Array.isArray(segs)) return "unknown";
    let known = 0, total = 0, active = false;
    for (const seg of segs) for (const ch of Object.values(seg.channels || {})) {
        if (ch?.channel === null || ch?.channel === undefined || ch.channel === "") continue;
        total++;
        const v = values[ch.channel];
        if (v !== undefined && v !== null) {
            known++;
            if (Number(v) > 0) active = true;
        }
    }
    return active ? "on" : (total > 0 && known === total ? "off" : "unknown");
}
function refreshStates() {
    for (const name of ["innen", "aussen", "position", "achtern", "top", "mast", "unterwasser"]) {
        if (config[name]) config[name].status = groupState(name);
    }
}
function ledMsg() {
    const s = groupState(area);
    return { area, topic: "state", payload: s === "on" ? "ein" : s === "off" ? "aus" : "unbekannt" };
}
if (topic === "refresh") {
    refreshStates();
    flow.set("nightMode", nm, STORE);
    flow.set("lights", root, STORE);
    return [null, ledMsg()];
}
if (!["toggle", "slider", "color", "colour", "rgb", "off", "alloff", "night_apply"].includes(topic)) {
    node.error("Unbekanntes Topic: " + topic, msg);
    return null;
}
if (topic === "night_apply" && !isRgb) return null;
// Gruppenstatus bestimmt Alles-AUS, nicht der letzte Bedienmodus.
const desiredOn = [...all.keys()].some(n => Number(desired[n] || 0) > 0);
if (topic === "alloff" && !desiredOn && groupState(area) === "off") {
    refreshStates();
    flow.set("nightMode", nm, STORE);
    flow.set("lights", root, STORE);
    return [null, ledMsg()];
}
const turnOn = topic === "toggle" && !desiredOn;
const normalCommand = topic !== "night_apply";
const shuttingDown = topic === "off" || topic === "alloff" || (topic === "toggle" && !turnOn);
const baseFade = Number(group["fade speed"]) || 0;
const transitionFade = Math.max(0, Number(msg.payload?.fadeMs) || 0);
const commands = new Map();

// Neue Sollwerte errechnen, bevor die Nachtmodus-Maske auf sie angewandt wird.
if (normalCommand) {
    for (const ch of all.values()) {
        const maxbright = clamp(ch.maxbright ?? 100);
        let v = 0;
        if (topic === "toggle") {
            if (turnOn) v = Math.min(clamp(ch["auto brightness"] ?? maxbright), maxbright);
        } else if (topic === "slider") {
            let minVal = clamp(ch.min_val ?? 0);
            let maxVal = clamp(ch.max_val ?? ch.maxbright ?? 100);
            if (maxVal < minVal) [minVal, maxVal] = [maxVal, minVal];
            v = minVal + (maxVal - minVal) * clamp(msg.payload) / 100;
        } else if (["color", "colour", "rgb"].includes(topic)) {
            const p = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
            v = Math.min(clamp(p[ch.color] ?? 0), maxbright);
        }
        desired[ch.channel] = v;
    }
}
const wantOn = [...all.keys()].some(n => Number(desired[n] || 0) > 0);
// Funktioniert auch bei reiner G/B-Farbwahl: nachts rote Grundbeleuchtung einschalten.
function physicalValue(ch) {
    const requested = clamp(desired[ch.channel] ?? 0);
    if (!nightActive || !wantOn) return requested;
    if (ch.color === "g" || ch.color === "b") return 0;
    if (ch.color === "r" && requested <= 0) {
        return Math.min(clamp(ch["auto brightness"] ?? ch.maxbright ?? 100), clamp(ch.maxbright ?? 100));
    }
    return requested;
}
