for (const ch of all.values()) {
    const output = physicalValue(ch);
    const previous = values[ch.channel];
    let delay = 0, fadeMs = 0;
    if (topic === "toggle" || topic === "alloff") {
        fadeMs = baseFade;
        delay = shuttingDown ? Math.max(0, Number(ch["off delay"]) || 0) : ch.delay;
    } else if (topic === "night_apply") {
        // Nur geaenderte Ausgangsziele werden ueberblendet; rote Kanaele bleiben sonst unangetastet.
        fadeMs = (ch.color === "g" || ch.color === "b") ? transitionFade : Math.min(1000, transitionFade);
    }
    if (topic !== "night_apply" || previous === undefined || Math.abs(Number(previous) - output) > 0.00001) {
        commands.set(ch.channel, { channel: ch.channel, value: output, fadeMs, delay });
    }
}
// Vorhandene Einschalt-Timer bei einem neuen Gruppenbefehl loeschen.
// Noch nicht abgeschickte Kanaele muessen bei night_apply neu ausgegeben werden.
const oldPending = context.get("pendingTimers") || [];
if (topic === "night_apply") {
    for (const pending of oldPending) {
        for (const n of pending.channels || []) {
            if (!commands.has(n) && all.has(n)) {
                const ch = all.get(n);
                commands.set(n, {
                    channel: n, value: physicalValue(ch),
                    fadeMs: ch.color === "g" || ch.color === "b" ? transitionFade : baseFade,
                    delay: 0
                });
            }
        }
    }
}
for (const pending of oldPending) clearTimeout(pending.timer || pending);
context.set("pendingTimers", []);
for (const command of commands.values()) values[command.channel] = command.value;
refreshStates();
if (normalCommand) {
    const state = groupState(area);
    areaCfg.mode = state === "off" ? "off" :
        topic === "toggle" ? "toggle" :
        topic === "slider" ? "slider" :
        ["color", "colour", "rgb"].includes(topic) ? "colour" : "off";
}
flow.set("nightMode", nm, STORE);
flow.set("lights", root, STORE);
node.send([null, ledMsg()]);
const byDelay = new Map();
for (const item of commands.values()) {
    if (!byDelay.has(item.delay)) byDelay.set(item.delay, []);
    byDelay.get(item.delay).push({ channel: item.channel, value: item.value, fadeMs: item.fadeMs });
}
const timers = [];
for (const [delay, items] of byDelay) {
    const out = { area, payload: { type: "set_multi", items } };
    if (delay > 0) {
        const t = setTimeout(() => {
            const remaining = (context.get("pendingTimers") || []).filter(p => p.timer !== t);
            context.set("pendingTimers", remaining);
            node.send([out, null]);
        }, delay);
        timers.push({timer:t, channels:items.map(x=>x.channel)});
    } else node.send([out, null]);
}
context.set("pendingTimers", timers);
return null;

