// Nachtmodus ausschließlich unter flow.nightMode (file).
// SignalK: flow.nightMode.dateTime.updates[0].values[0].value (day/night)
// Hafen: global.BoatState.atHabour (memory; inside/outside)
// Ausgang 1: night_apply an Innen/Aussen. Ausgang 2: Dashboard.
const FILE = "file", MEMORY = "memory";
const nm = flow.get("nightMode", FILE) || {};
if (!["auto", "on", "off"].includes(nm.mode)) nm.mode = "auto";
if (typeof nm.active !== "boolean") nm.active = false;
if (typeof nm.resolved !== "boolean") nm.resolved = false;
const before = nm.active;
const previousNight = nm.signalK;
const previousHarbor = nm.inHarbor;
const raw = nm.dateTime?.updates?.[0]?.values?.[0]?.value;
const dayNight = String(raw ?? "").trim().toLowerCase();
nm.signalK = ["day", "night"].includes(dayNight) ? dayNight : "unknown";
const boat = global.get("BoatState", MEMORY);
const place = String(boat?.atHabour ?? "").trim().toLowerCase();
nm.inHarbor = place === "inside" ? true : place === "outside" ? false : null;
const nightChanged = nm.signalK !== previousNight;
const harborChanged = nm.inHarbor !== previousHarbor;
const topic = String(msg.topic || "").trim().toLowerCase();
let cause = "refresh";
const manual = topic === "night_cycle";
if (manual) {
    nm.mode = nm.mode === "auto" ? "on" : nm.mode === "on" ? "off" : "auto";
    cause = "manual";
} else if (!["", "poll", "refresh", "refresh_night", "signalk", "harbor_update"].includes(topic)) return null;
if (!manual) {
    if (nightChanged) cause = "signalk";
    else if (harborChanged) cause = "harbor";
}
let target = null;
if (nm.mode === "on") target = true;
else if (nm.mode === "off") target = false;
else if (nm.signalK === "day") target = false;
else if (nm.signalK === "night" && nm.inHarbor !== null) target = !nm.inHarbor;
let changed = false, fadeMs = 0;
if (target !== null) {
    changed = !nm.resolved || target !== before;
    nm.active = target;
    nm.resolved = true;
    if (changed) {
        fadeMs = manual ? 1000 : cause === "harbor" ? 10000 : 60000;
        nm.lastTransition = {cause, fadeMs, active:nm.active, timestamp:new Date().toISOString()};
    }
}
flow.set("nightMode", nm, FILE);
const modeLabel = nm.mode === "auto" ? "AUTO" : nm.mode === "on" ? "NACHT EIN" : "NACHT AUS";
const effect = !nm.resolved ? "unbekannt" : nm.active ? "nur Rot" : "RGB";
const harbor = nm.inHarbor === null ? "Hafen unbekannt" : nm.inHarbor ? "im Hafen" : "außerhalb Hafen";
const label = `${modeLabel} | ${effect} | SignalK: ${nm.signalK} | ${harbor}`;
node.status({fill:!nm.resolved ? "grey" : nm.active ? "yellow" : "green", shape:"dot",text:label});
const text = {payload:label};
if (!changed) return [null,text];
return [{topic:"night_apply",payload:{night:nm.active,fadeMs,cause}},text];
